task.spawn(function()
    while true do
        if speedOn then
            local h = humanoid()
            if h then pcall(function() h.WalkSpeed = walkSpeedVal end) end
            local sp = swimPart()
            if sp and h and not flyConn then
                local bv = sp:FindFirstChild("SwimBv"); if bv then bv.MaxForce = Vector3.zero end
                local r = rootPart()
                if r then
                    local mv = h.MoveDirection
                    local horiz = (mv.Magnitude > 0) and (mv.Unit * walkSpeedVal) or Vector3.zero
                    r.AssemblyLinearVelocity = Vector3.new(horiz.X, 0, horiz.Z)
                end
            end
        end
        RunService.Heartbeat:Wait()
    end
end)

