local STAFF_LISTS = { "Owner", "CoOwner", "Developer", "Special", "Youtuber" }
local _staff
local function staffSet()
    if _staff then return _staff end
    _staff = {}
    local gd = gameData()
    if gd then
        for _, key in ipairs(STAFF_LISTS) do
            local list = gd[key]
            if type(list) == "table" then
                for _, id in ipairs(list) do _staff[id] = key end
            end
        end
    end
    return _staff
end
local function staffRoleOf(plr) return staffSet()[plr.UserId] end
local ROLE_LABEL = { Owner = L["an Owner"], CoOwner = L["a Co Owner"], Developer = L["a Developer"], Special = L["a Special player"], Youtuber = L["a Content Creator"] }
local function kickSelf(name, role)
    pcall(function() lp:Kick(L["Staff Watch: "] .. name .. L[" is "] .. (ROLE_LABEL[role] or role) .. L[". You were removed so you do not get reported."]) end)
end
local staffConn
local function setStaffWatch(on)
    if staffConn then staffConn:Disconnect(); staffConn = nil end
    if not on then return end
    for _, p in ipairs(Players:GetPlayers()) do
        if p ~= lp then
            local role = staffRoleOf(p)
            if role then kickSelf(p.Name, role); return end
        end
    end
    staffConn = Players.PlayerAdded:Connect(function(p)
        local role = staffRoleOf(p)
        if role then kickSelf(p.Name, role) end
    end)
end

